#pragma once
// AETHER 2.3.0 segment B - Controlled Randomization engine, phase P1 (pure functions).
//
// * No JUCE, no globals, no I/O.  generate() depends only on its arguments.
// * NOT realtime-safe: Patch holds a std::vector, so generate()/validate() allocate.  Call them on the message or a worker
//   thread; nothing here is meant for the audio thread.
// * Table driven: libs/aether-rand/src/RandTable.inc is generated by tools/gen_rand_table.py from docs/randomization-spec*.
// * Values in StateView / Patch are parameter UNIT values (dB, Hz, 0..1 ...), in parameterSpecs() order (spec P.1).
// * Reproducibility is promised on Windows/MSVC (spec 6.1).  The sampler only uses IEEE +,-,*,/ , frexp and ldexp (own
//   log2/exp2, no libm transcendental), so other compilers are expected to match; the golden test shows MSVC == clang here.
#include <array>
#include <bitset>
#include <cstdint>
#include <span>
#include <string_view>
#include <vector>

namespace aether::rand {

inline constexpr int kRandAlgoVersion = 1;
inline constexpr int kParamCount = 495;
inline constexpr int kModuleTypeCount = 21;
inline constexpr int kFmAlgorithmCount = 32;
inline constexpr int kRouteAlgorithmCount = 32;
inline constexpr int kSlotCount = 12;
inline constexpr int kModRowCount = 16;

// parameterSpecs() layout (checked against the real specs by aether_rand_coverage).
inline constexpr int kGraphOffset = 39, kNodeOffset = 43, kRouteOffset = 175, kLfoOffset = 319, kModOffset = 335, kFmOffset = 383,
                     kOpOffset = 395, kEdgeOffset = 431, kSourceOffset = 467;
inline constexpr int kGraphEnabled = kGraphOffset, kRoutingAlgorithm = kGraphOffset + 1, kGraphFeedback = kGraphOffset + 2,
                     kGraphTrim = kGraphOffset + 3;
inline constexpr int nodeParam(int slot, int field) noexcept { return kNodeOffset + slot * 11 + field; }  // field: type,on,mix,level,pan,a,b,c,d,input,output
inline constexpr int lfoParam(int lfo, int field) noexcept { return kLfoOffset + lfo * 4 + field; }       // rate,phase,shape,sync
inline constexpr int modParam(int row, int field) noexcept { return kModOffset + row * 3 + field; }       // source,target,depth
inline constexpr int opParam(int op, int field) noexcept { return kOpOffset + op * 6 + field; }           // ratio,level,carrier,detune,attack,release
inline constexpr int kFmEnabled = kFmOffset, kFmAlgorithm = kFmOffset + 1, kFmCustom = kFmOffset + 2, kFmIndex = kFmOffset + 3,
                     kFmMorph = kFmOffset + 4, kFmFeedback = kFmOffset + 5;
inline constexpr int kSourceEngine = kSourceOffset, kSourceEnabled = kSourceOffset + 1;

// ---- deterministic building blocks (public so the tests can pin them) ----------------------------------------------
inline constexpr std::uint64_t fnv1a64(std::string_view s) noexcept {
    std::uint64_t h = 0xcbf29ce484222325ULL;
    for (char c : s) { h ^= static_cast<std::uint8_t>(c); h *= 0x100000001b3ULL; }
    return h;
}
// Standard PCG32 (XSH-RR, O'Neill): Pcg32(initstate, initseq) == pcg32_srandom_r(initstate, initseq).
struct Pcg32 {
    std::uint64_t state = 0, inc = 0;
    constexpr Pcg32(std::uint64_t initstate, std::uint64_t initseq) noexcept {
        inc = (initseq << 1u) | 1u;
        next32();
        state += initstate;
        next32();
    }
    constexpr std::uint32_t next32() noexcept {
        const std::uint64_t old = state;
        state = old * 6364136223846793005ULL + inc;
        const std::uint32_t xorshifted = static_cast<std::uint32_t>(((old >> 18u) ^ old) >> 27u);
        const std::uint32_t rot = static_cast<std::uint32_t>(old >> 59u);
        return (xorshifted >> rot) | (xorshifted << ((~rot + 1u) & 31u));
    }
    // u = (next32() >> 8) * 2^-24: exactly representable in float, in [0,1).
    constexpr double nextUnit() noexcept { return static_cast<double>(next32() >> 8) * (1.0 / 16777216.0); }
};
// Own log2/exp2 built from + - * / frexp ldexp only (no libm transcendental), |error| < 1e-13 for the ranges used here.
double log2Det(double x) noexcept;   // x > 0
double exp2Det(double x) noexcept;
double powDet(double base, double exponent) noexcept;  // base > 0

// ---- configuration --------------------------------------------------------------------------------------------------
enum class Mode { Full, Mutate };
enum class Safety { Safe, Normal, Wild };
enum ScopeBits : std::uint32_t { ScopeChain = 1, ScopeModuleParams = 2, ScopeFM = 4, ScopeSource = 8, ScopeMotion = 16, ScopeAll = 31 };

struct EditionContext {      // filled by the processor; the engine never writes global.mode
    int effectiveMode = 0;   // 0 FX / 1 Resynth / 2 Synth (effectiveMode())
    bool isSynth = false;
};

struct Config {
    std::uint64_t seed = 0;          // 40 significant bits for callers; any 64-bit value is accepted
    Mode mode = Mode::Full;
    float amount = 1.f;              // 0..1; Mutate only (Full ignores it). Mutate with amount == 0 yields an empty patch
    Safety safety = Safety::Safe;    // frozen default (spec 9.1.1 #2; draft P.1 said Normal)
    std::uint32_t scopeMask = ScopeAll;
    int attempt = 0;                 // re-roll index 0..5 (6.1): attemptSeed = seed ^ (k * 0x9E3779B97F4A7C15)
    bool intoB = false;              // only affects where the caller writes; does not affect sampling
};

struct StateView {
    std::array<float, kParamCount> value{};  // unit values in parameterSpecs() order
    EditionContext edition{};
};

// Lock section bits (LockSet::sections).
inline constexpr std::uint32_t kLockSlot0 = 1u << 0;  // bit s = node slot s (0-based, 12 slots, 11 params each)
inline constexpr std::uint32_t kLockFm = 1u << 12;    // fm.*, fm.op.*, fm.edge.*
inline constexpr std::uint32_t kLockSource = 1u << 13;
inline constexpr std::uint32_t kLockLfo0 = 1u << 14;  // bit 14+l = lfo l (0-based)
inline constexpr std::uint32_t kLockMod = 1u << 18;   // all 16 modulation rows

struct LockSet {
    std::bitset<kParamCount> params;  // per parameter, by spec index
    std::uint32_t sections = 0;
    std::uint16_t modRows = 0;        // bit r = modulation row r (source,target,depth together)
    bool isLocked(int specIndex) const noexcept;
};

struct Patch {
    struct Diff { int specIndex; float value; };  // unit value
    std::vector<Diff> diffs;                      // only entries that differ bitwise from the input, ascending specIndex
    struct Report {
        bool ok = true;
        const char* reason = "ok";
        int activeSlots = 0;       // of the resulting state
        int algorithm = 0;
        int modulationRows = 0;    // rows with source != None and target != None
    } report;
};

Patch generate(const StateView&, const Config&, const LockSet&) noexcept;
// Independent rule check of `before + patch` (spec 7.2). Returns ok=false with a reason for the first violated rule.
Patch::Report validate(const StateView& before, const Patch&, const Config&, const LockSet&);
std::array<float, kParamCount> applyPatch(const StateView&, const Patch&) noexcept;
// Loudness compensation helper for the audition phase: trim = clamp(target - measured, -24, 0) dB (spec 7.3, frozen 9.1.1 #4).
float trimDbForLoudness(float measuredDb, float targetDb = -18.f) noexcept;

// ---- static tables (generated) -------------------------------------------------------------------------------------
enum class ParamType : std::uint8_t { Float, Choice, Bool };
enum class Classification : std::uint8_t { Random, Structural, Never };
enum class Group : std::uint8_t { Chain, ModuleParams, FM, Source, Motion, MixGlobal, System };
enum class Role : std::uint8_t { Never, Structural, Value, Choice, ModSource, ModDest, ModDepth };
enum class Dist : std::uint8_t { None, Uniform, Log, Kumaraswamy, Centered, Sparse, PerType, Choice, Bool, Derived };
enum class ActiveWhen : std::uint8_t {
    None, ClassicOnly, GraphOn, GraphFeedbackAlgo, NodeActive, GraphAlgo32, LfoReferenced, RowLive, ModeRS, FmOnModeRS, FmOn,
    FmOnNotFx, FmOnCustom0, FmOnCustom1, SrcOn, SrcEngine1, SrcEngine2
};
struct Window { double lo, hi; };
struct ParamInfo {
    const char* id;
    std::uint64_t hash;           // fnv1a64(id): the per-parameter PCG32 stream id
    ParamType type;
    Classification cls;
    Group group;
    Role role;
    ActiveWhen active;
    Dist dist;
    int safetyClass;              // S0..S8
    bool rsOnly;                  // edition column RS: skipped when the effective mode is FX
    int numChoices;               // 0 for float/bool
    double minV, maxV, step, defaultV;  // parameterSpecs() (unit values)
    double ka, kb;                // Kumaraswamy shape
    double sparseP[3];            // Sparse: P(non-zero) for Safe/Normal/Wild
    Window win[3];                // Safe / Normal / Wild window (unit values; zero for Never, per-type and set rows)
};
struct MacroInfo {
    Dist dist;
    double ka, kb, center;
    double sparseP[3];
    Window win[3];
    int safetyClass;
    double defaultV;
};
struct FmAlgoInfo { unsigned carrierMask, unreachableMask; int edges, selfEdges; bool hasCycle; double maxIncoming; };
struct RouteAlgoInfo { int forwardEdges, feedbackArcs; double minInputScale; };

std::span<const ParamInfo, kParamCount> paramTable() noexcept;
const MacroInfo& macroInfo(int moduleType, int knob) noexcept;
const FmAlgoInfo& fmAlgoInfo(int algorithm) noexcept;
const RouteAlgoInfo& routeAlgoInfo(int algorithm) noexcept;
int paramIndex(std::string_view id) noexcept;  // -1 when unknown

}  // namespace aether::rand
